package com.comandos.logistics;

import com.comandos.security.service.ComandosAccessPolicy;
import com.fariamiguel.enterprise.logistics.LogisticsDirectory;
import com.fariamiguel.enterprise.logistics.LogisticsService;
import com.fariamiguel.security.api.CurrentActorProvider;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.web.bind.annotation.*;

/** COMANDOS adapter for generic stock logistics; sector specific custody remains in the product module. */
@RestController
@RequestMapping("/api/erp/logistics")
public final class ComandosLogisticsController {
    private static final String TENANT="comandos";
    private static final String RESOURCE="inventory/logistics";
    private final LogisticsService service;
    private final ComandosAccessPolicy access;
    private final CurrentActorProvider actors;

    public ComandosLogisticsController(LogisticsService service,ComandosAccessPolicy access,CurrentActorProvider actors){this.service=Objects.requireNonNull(service);this.access=Objects.requireNonNull(access);this.actors=Objects.requireNonNull(actors);}

    @PostMapping("/bins")
    public LogisticsDirectory.WarehouseBin saveBin(@RequestBody BinRequest b){require("CREATE",b.organizationId(),b.unitId());Map<String,String> metadata=scope(b.organizationId(),b.unitId());return service.saveWarehouseBin(new LogisticsDirectory.WarehouseBin(b.id(),TENANT,b.warehouseId(),b.parentBinId(),b.code(),b.name(),b.unitOfMeasure(),b.capacity(),true,metadata));}
    @GetMapping("/bins")
    public List<LogisticsDirectory.WarehouseBin> bins(@RequestParam long organizationId,@RequestParam(required=false) Long unitId,@RequestParam(required=false) String warehouseId){require("READ",organizationId,unitId);return service.warehouseBins(TENANT,warehouseId).stream().filter(x->within(x.metadata(),organizationId,unitId)).toList();}
    @PostMapping("/lots")
    public LogisticsDirectory.InventoryLot registerLot(@RequestBody LotRequest b){require("CREATE",b.organizationId(),b.unitId());return service.registerInventoryLot(new LogisticsDirectory.InventoryLot(b.id(),TENANT,b.productId(),b.lotNumber(),b.manufacturedOn(),b.expiresOn(),b.supplierId(),b.originReference(),b.status()==null?LogisticsDirectory.LotStatus.ACTIVE:b.status(),b.registeredAt()==null?Instant.now():b.registeredAt(),actor(),scope(b.organizationId(),b.unitId())));}
    @GetMapping("/lots")
    public List<LogisticsDirectory.InventoryLot> lots(@RequestParam long organizationId,@RequestParam(required=false) Long unitId,@RequestParam(required=false) String productId){require("READ",organizationId,unitId);return service.inventoryLots(TENANT,productId).stream().filter(x->within(x.metadata(),organizationId,unitId)).toList();}
    @PutMapping("/lots/{id}/status")
    public LogisticsDirectory.InventoryLot updateLotStatus(@PathVariable String id,@RequestParam long organizationId,@RequestParam(required=false) Long unitId,@RequestBody LotStatusRequest b){require("UPDATE",organizationId,unitId);requireLot(id,organizationId,unitId);return service.updateInventoryLotStatus(TENANT,id,b.status(),actor());}
    @PostMapping("/bins/{binId}/receipts")
    public LogisticsDirectory.InventoryMovement receive(@PathVariable String binId,@RequestParam long organizationId,@RequestParam(required=false) Long unitId,@RequestBody ReceiptRequest b){require("CREATE",organizationId,unitId);requireBin(binId,organizationId,unitId);var movement=new LogisticsDirectory.InventoryMovement(b.id(),TENANT,b.productId(),b.lotId(),binId,LogisticsDirectory.InventoryMovementType.RECEIPT,b.quantity(),b.unitOfMeasure(),b.occurredAt()==null?Instant.now():b.occurredAt(),b.referenceType(),b.referenceId(),actor(),b.unitCost(),b.currency(),scope(organizationId,unitId));return service.recordInventoryMovement(movement);}
    @PostMapping("/bins/{binId}/adjustments")
    public LogisticsDirectory.InventoryMovement adjust(@PathVariable String binId,@RequestParam long organizationId,@RequestParam(required=false) Long unitId,@RequestBody AdjustmentRequest b){require("UPDATE",organizationId,unitId);requireBin(binId,organizationId,unitId);if(b.type()!=LogisticsDirectory.InventoryMovementType.ADJUSTMENT_IN&&b.type()!=LogisticsDirectory.InventoryMovementType.ADJUSTMENT_OUT)throw new IllegalArgumentException("inventory adjustment must be an increase or decrease");return service.recordInventoryMovement(new LogisticsDirectory.InventoryMovement(b.id(),TENANT,b.productId(),b.lotId(),binId,b.type(),b.quantity(),b.unitOfMeasure(),b.occurredAt()==null?Instant.now():b.occurredAt(),"COUNT_ADJUSTMENT",b.referenceId(),actor(),b.unitCost(),b.currency(),scope(organizationId,unitId)));}
    @GetMapping("/bins/{binId}/balances")
    public List<LogisticsDirectory.InventoryBalance> balances(@PathVariable String binId,@RequestParam long organizationId,@RequestParam(required=false) Long unitId,@RequestParam String productId,@RequestParam String unitOfMeasure){require("READ",organizationId,unitId);requireBin(binId,organizationId,unitId);return service.inventoryBalances(TENANT,productId,binId,unitOfMeasure).stream().filter(b->b.onHand().signum()>0||b.reserved().signum()>0).toList();}
    @GetMapping("/bins/{binId}/valuation")
    public LogisticsDirectory.InventoryValuation valuation(@PathVariable String binId,@RequestParam long organizationId,@RequestParam(required=false) Long unitId,@RequestParam String productId,@RequestParam(required=false) String lotId,@RequestParam String unitOfMeasure,@RequestParam(defaultValue="WEIGHTED_AVERAGE") LogisticsDirectory.InventoryCostingMethod method){require("READ",organizationId,unitId);requireBin(binId,organizationId,unitId);if(lotId!=null)requireLot(lotId,organizationId,unitId);return service.inventoryValuation(TENANT,productId,lotId,binId,unitOfMeasure,method);}
    @GetMapping("/bins/{binId}/movements")
    public List<LogisticsDirectory.InventoryMovement> movements(@PathVariable String binId,@RequestParam long organizationId,@RequestParam(required=false) Long unitId,@RequestParam(required=false) String productId){require("READ",organizationId,unitId);requireBin(binId,organizationId,unitId);return service.inventoryMovements(TENANT,productId,binId).stream().filter(x->within(x.metadata(),organizationId,unitId)).toList();}
    @PostMapping("/bins/{binId}/reservations")
    public LogisticsDirectory.InventoryReservation reserve(@PathVariable String binId,@RequestParam long organizationId,@RequestParam(required=false) Long unitId,@RequestBody ReservationRequest b){require("UPDATE",organizationId,unitId);requireBin(binId,organizationId,unitId);if(b.lotId()!=null)requireLot(b.lotId(),organizationId,unitId);return service.reserveInventory(new LogisticsDirectory.InventoryReservation(b.id(),TENANT,b.productId(),b.lotId(),binId,b.quantity(),b.unitOfMeasure(),b.referenceType(),b.referenceId(),LogisticsDirectory.ReservationStatus.ACTIVE,b.createdAt()==null?Instant.now():b.createdAt(),b.expiresAt(),actor(),scope(organizationId,unitId)));}
    @PostMapping("/bins/{binId}/reservations/fefo")
    public List<LogisticsDirectory.InventoryReservation> reserveFefo(@PathVariable String binId,@RequestParam long organizationId,@RequestParam(required=false) Long unitId,@RequestBody FefoReservationRequest b){require("UPDATE",organizationId,unitId);requireBin(binId,organizationId,unitId);return service.reserveInventoryFefo(TENANT,b.id(),b.productId(),binId,b.quantity(),b.unitOfMeasure(),b.referenceType(),b.referenceId(),b.expiresAt(),actor());}
    @GetMapping("/bins/{binId}/reservations")
    public List<LogisticsDirectory.InventoryReservation> reservations(@PathVariable String binId,@RequestParam long organizationId,@RequestParam(required=false) Long unitId,@RequestParam(required=false) String productId){require("READ",organizationId,unitId);requireBin(binId,organizationId,unitId);return service.inventoryReservations(TENANT,productId,binId);}
    @PostMapping("/reservations/{id}/release")
    public LogisticsDirectory.InventoryReservation releaseReservation(@PathVariable String id,@RequestParam long organizationId,@RequestParam(required=false) Long unitId){require("UPDATE",organizationId,unitId);var reservation=requireReservation(id,organizationId,unitId);return service.releaseReservation(TENANT,id,actor());}
    @PostMapping("/reservations/{id}/fulfill")
    public LogisticsDirectory.InventoryReservation fulfillReservation(@PathVariable String id,@RequestParam long organizationId,@RequestParam(required=false) Long unitId){require("UPDATE",organizationId,unitId);requireReservation(id,organizationId,unitId);return service.fulfillReservation(TENANT,id,actor());}
    @PostMapping("/transfers")
    public LogisticsDirectory.InventoryTransfer transfer(@RequestBody TransferRequest b){require("UPDATE",b.organizationId(),b.unitId());requireBin(b.sourceLocationId(),b.organizationId(),b.unitId());requireBin(b.destinationLocationId(),b.organizationId(),b.unitId());if(b.lotId()!=null)requireLot(b.lotId(),b.organizationId(),b.unitId());return service.transferInventory(new LogisticsDirectory.InventoryTransfer(b.id(),TENANT,b.productId(),b.lotId(),b.sourceLocationId(),b.destinationLocationId(),b.quantity(),b.unitOfMeasure(),b.occurredAt()==null?Instant.now():b.occurredAt(),b.referenceType(),b.referenceId(),actor(),scope(b.organizationId(),b.unitId())));}
    @GetMapping("/transfers")
    public List<LogisticsDirectory.InventoryTransfer> transfers(@RequestParam long organizationId,@RequestParam(required=false) Long unitId,@RequestParam(required=false) String productId){require("READ",organizationId,unitId);return service.inventoryTransfers(TENANT,productId).stream().filter(x->within(x.metadata(),organizationId,unitId)).toList();}
    @PostMapping("/shipments")
    public LogisticsDirectory.Shipment createShipment(@RequestBody ShipmentRequest b){require("CREATE",b.organizationId(),b.unitId());requireBin(b.originLocationId(),b.organizationId(),b.unitId());requireBin(b.destinationLocationId(),b.organizationId(),b.unitId());return service.saveShipment(new LogisticsDirectory.Shipment(b.id(),TENANT,b.reference(),b.originLocationId(),b.destinationLocationId(),b.carrier(),b.trackingNumber(),LogisticsDirectory.ShipmentStatus.PLANNED,b.plannedAt()==null?Instant.now():b.plannedAt(),null,null,b.recipient(),b.notes(),scope(b.organizationId(),b.unitId())));}
    @GetMapping("/shipments")
    public List<LogisticsDirectory.Shipment> shipments(@RequestParam long organizationId,@RequestParam(required=false) Long unitId){require("READ",organizationId,unitId);return service.shipments(TENANT).stream().filter(x->within(x.metadata(),organizationId,unitId)).toList();}
    @PostMapping("/shipments/{id}/items")
    public LogisticsDirectory.ShipmentItem addShipmentItem(@PathVariable String id,@RequestParam long organizationId,@RequestParam(required=false) Long unitId,@RequestBody ShipmentItemRequest b){require("UPDATE",organizationId,unitId);requireShipment(id,organizationId,unitId);if(b.lotId()!=null)requireLot(b.lotId(),organizationId,unitId);return service.addShipmentItem(new LogisticsDirectory.ShipmentItem(b.id(),TENANT,id,b.productId(),b.lotId(),b.serialNumber(),b.quantity(),b.unitOfMeasure(),b.metadata()));}
    @GetMapping("/shipments/{id}/items")
    public List<LogisticsDirectory.ShipmentItem> shipmentItems(@PathVariable String id,@RequestParam long organizationId,@RequestParam(required=false) Long unitId){require("READ",organizationId,unitId);requireShipment(id,organizationId,unitId);return service.shipmentItems(TENANT,id);}
    @PostMapping("/shipments/{id}/events")
    public LogisticsDirectory.ShipmentEvent recordShipmentEvent(@PathVariable String id,@RequestParam long organizationId,@RequestParam(required=false) Long unitId,@RequestBody ShipmentEventRequest b){require("UPDATE",organizationId,unitId);requireShipment(id,organizationId,unitId);if(b.locationId()!=null)requireBin(b.locationId(),organizationId,unitId);return service.recordShipmentEvent(new LogisticsDirectory.ShipmentEvent(b.id(),TENANT,id,b.type(),b.occurredAt()==null?Instant.now():b.occurredAt(),b.locationId(),b.description(),b.evidenceReference(),actor(),b.metadata()));}
    @GetMapping("/shipments/{id}/events")
    public List<LogisticsDirectory.ShipmentEvent> shipmentEvents(@PathVariable String id,@RequestParam long organizationId,@RequestParam(required=false) Long unitId){require("READ",organizationId,unitId);requireShipment(id,organizationId,unitId);return service.shipmentEvents(TENANT,id);}
    @PostMapping("/imports")
    public LogisticsDirectory.ImportProcess createImport(@RequestBody ImportRequest b){require("CREATE",b.organizationId(),b.unitId());requireBin(b.destinationLocationId(),b.organizationId(),b.unitId());if(b.shipmentId()!=null)requireShipment(b.shipmentId(),b.organizationId(),b.unitId());return service.saveImport(new LogisticsDirectory.ImportProcess(b.id(),TENANT,b.reference(),b.supplierId(),b.supplierCountry(),b.purchaseReference(),b.currency(),b.exchangeRate(),LogisticsDirectory.ImportStatus.PLANNED,b.shipmentId(),b.orderedOn(),b.estimatedArrival(),null,null,null,b.destinationLocationId(),b.notes(),scope(b.organizationId(),b.unitId())),actor());}
    @GetMapping("/imports")
    public List<LogisticsDirectory.ImportProcess> imports(@RequestParam long organizationId,@RequestParam(required=false) Long unitId){require("READ",organizationId,unitId);return service.imports(TENANT).stream().filter(x->within(x.metadata(),organizationId,unitId)).toList();}
    @PostMapping("/imports/{id}/status")
    public LogisticsDirectory.ImportProcess updateImportStatus(@PathVariable String id,@RequestParam long organizationId,@RequestParam(required=false) Long unitId,@RequestBody ImportStatusRequest b){require("UPDATE",organizationId,unitId);var old=requireImport(id,organizationId,unitId);return service.saveImport(new LogisticsDirectory.ImportProcess(old.id(),old.tenant(),old.reference(),old.supplierId(),old.supplierCountry(),old.purchaseReference(),old.currency(),old.exchangeRate(),b.status(),old.shipmentId(),old.orderedOn(),old.estimatedArrival(),b.arrivedOn()==null?old.arrivedOn():b.arrivedOn(),b.clearedOn()==null?old.clearedOn():b.clearedOn(),b.customsReference()==null?old.customsReference():b.customsReference(),old.destinationLocationId(),b.notes()==null?old.notes():b.notes(),old.metadata()),actor());}
    @GetMapping("/imports/{id}/history")
    public List<LogisticsDirectory.ImportStatusTransition> importHistory(@PathVariable String id,@RequestParam long organizationId,@RequestParam(required=false) Long unitId){require("READ",organizationId,unitId);requireImport(id,organizationId,unitId);return service.importStatusHistory(TENANT,id);}
    @PostMapping("/imports/{id}/documents")
    public LogisticsDirectory.ImportFile addImportDocument(@PathVariable String id,@RequestParam long organizationId,@RequestParam(required=false) Long unitId,@RequestBody ImportDocumentRequest b){require("UPDATE",organizationId,unitId);requireImport(id,organizationId,unitId);return service.addImportFile(new LogisticsDirectory.ImportFile(b.id(),TENANT,id,b.type(),b.documentReference(),b.fileName(),b.checksum(),b.registeredAt()==null?Instant.now():b.registeredAt(),actor(),b.metadata()));}
    @GetMapping("/imports/{id}/documents")
    public List<LogisticsDirectory.ImportFile> importDocuments(@PathVariable String id,@RequestParam long organizationId,@RequestParam(required=false) Long unitId){require("READ",organizationId,unitId);requireImport(id,organizationId,unitId);return service.importFiles(TENANT,id);}
    @PostMapping("/imports/{id}/expenses")
    public LogisticsDirectory.ImportExpense addImportExpense(@PathVariable String id,@RequestParam long organizationId,@RequestParam(required=false) Long unitId,@RequestBody ImportExpenseRequest b){require("UPDATE",organizationId,unitId);requireImport(id,organizationId,unitId);return service.addImportExpense(new LogisticsDirectory.ImportExpense(b.id(),TENANT,id,b.category(),b.amount(),b.currency(),b.exchangeRate(),b.baseCurrencyAmount(),b.incurredOn(),b.documentReference(),b.notes(),b.metadata()));}
    @GetMapping("/imports/{id}/expenses")
    public List<LogisticsDirectory.ImportExpense> importExpenses(@PathVariable String id,@RequestParam long organizationId,@RequestParam(required=false) Long unitId){require("READ",organizationId,unitId);requireImport(id,organizationId,unitId);return service.importExpenses(TENANT,id);}
    @PostMapping("/imports/{id}/lines")
    public LogisticsDirectory.ImportLine addImportLine(@PathVariable String id,@RequestParam long organizationId,@RequestParam(required=false) Long unitId,@RequestBody ImportLineRequest b){require("UPDATE",organizationId,unitId);requireImport(id,organizationId,unitId);if(b.lotId()!=null)requireLot(b.lotId(),organizationId,unitId);return service.registerImportLine(new LogisticsDirectory.ImportLine(b.id(),TENANT,id,b.productId(),b.lotId(),b.quantity(),b.unitOfMeasure(),b.unitPrice(),b.currency(),b.exchangeRate(),b.baseUnitPrice(),b.baseCurrency(),b.supplierLineReference(),scope(organizationId,unitId)));}
    @GetMapping("/imports/{id}/lines")
    public List<LogisticsDirectory.ImportLine> importLines(@PathVariable String id,@RequestParam long organizationId,@RequestParam(required=false) Long unitId){require("READ",organizationId,unitId);requireImport(id,organizationId,unitId);return service.importLines(TENANT,id);}
    @GetMapping("/imports/{id}/lines/{lineId}/landed-cost")
    public LogisticsDirectory.ImportLineCost landedCost(@PathVariable String id,@PathVariable String lineId,@RequestParam long organizationId,@RequestParam(required=false) Long unitId){require("READ",organizationId,unitId);requireImport(id,organizationId,unitId);var line=requireImportLine(id,lineId,organizationId,unitId);return service.importLineLandedCost(TENANT,line.id());}
    @PostMapping("/imports/{id}/lines/{lineId}/receipts")
    public LogisticsDirectory.InventoryMovement receiveImportLine(@PathVariable String id,@PathVariable String lineId,@RequestParam long organizationId,@RequestParam(required=false) Long unitId,@RequestBody ImportLineReceiptRequest b){require("UPDATE",organizationId,unitId);requireImport(id,organizationId,unitId);requireImportLine(id,lineId,organizationId,unitId);return service.receiveImportLine(TENANT,lineId,b.receiptId(),b.quantity(),b.occurredAt(),actor());}

    private void require(String action,long organizationId,Long unitId){if(organizationId<=0||unitId!=null&&unitId<=0)throw new IllegalArgumentException("organization and unit IDs must be positive");access.requireScope(RESOURCE,action,organizationId,unitId);}
    private LogisticsDirectory.WarehouseBin requireBin(String id,long organizationId,Long unitId){var bin=service.directory().find(TENANT,id,LogisticsDirectory.WarehouseBin.class).orElseThrow(()->new IllegalArgumentException("warehouse bin does not exist"));if(!within(bin.metadata(),organizationId,unitId))throw new AccessDeniedException("Warehouse bin is outside selected organization and unit.");return bin;}
    private LogisticsDirectory.InventoryLot requireLot(String id,long organizationId,Long unitId){var lot=service.directory().find(TENANT,id,LogisticsDirectory.InventoryLot.class).orElseThrow(()->new IllegalArgumentException("inventory lot does not exist"));if(!within(lot.metadata(),organizationId,unitId))throw new AccessDeniedException("Inventory lot is outside selected organization and unit.");return lot;}
    private LogisticsDirectory.InventoryReservation requireReservation(String id,long organizationId,Long unitId){var reservation=service.inventoryReservations(TENANT,null,null).stream().filter(r->r.id().equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("inventory reservation does not exist"));requireBin(reservation.locationId(),organizationId,unitId);return reservation;}
    private LogisticsDirectory.Shipment requireShipment(String id,long organizationId,Long unitId){var shipment=service.requireShipment(TENANT,id);if(!within(shipment.metadata(),organizationId,unitId))throw new AccessDeniedException("Shipment is outside selected organization and unit.");return shipment;}
    private LogisticsDirectory.ImportProcess requireImport(String id,long organizationId,Long unitId){var value=service.directory().find(TENANT,id,LogisticsDirectory.ImportProcess.class).orElseThrow(()->new IllegalArgumentException("import process does not exist"));if(!within(value.metadata(),organizationId,unitId))throw new AccessDeniedException("Import process is outside selected organization and unit.");return value;}
    private LogisticsDirectory.ImportLine requireImportLine(String importId,String lineId,long organizationId,Long unitId){var value=service.directory().find(TENANT,lineId,LogisticsDirectory.ImportLine.class).orElseThrow(()->new IllegalArgumentException("import line does not exist"));if(!value.importId().equals(importId)||!within(value.metadata(),organizationId,unitId))throw new AccessDeniedException("Import line is outside selected import or organization and unit.");return value;}
    private static boolean within(Map<String,String> metadata,long organizationId,Long unitId){return Long.toString(organizationId).equals(metadata.get("organizationId"))&&(unitId==null||Objects.equals(Long.toString(unitId),metadata.get("unitId")));}
    private static Map<String,String> scope(long organizationId,Long unitId){Map<String,String> result=new HashMap<>();result.put("organizationId",Long.toString(organizationId));if(unitId!=null)result.put("unitId",Long.toString(unitId));return Map.copyOf(result);}
    private String actor(){var current=actors.currentActor();if(current==null||!current.authenticated()||current.id()==null||current.id().isBlank()||current.id().equalsIgnoreCase("anonymous"))throw new AccessDeniedException("An authenticated actor is required.");return current.id();}

    public record BinRequest(String id,long organizationId,Long unitId,String warehouseId,String parentBinId,String code,String name,String unitOfMeasure,BigDecimal capacity){}
    public record LotRequest(String id,long organizationId,Long unitId,String productId,String lotNumber,java.time.LocalDate manufacturedOn,java.time.LocalDate expiresOn,String supplierId,String originReference,LogisticsDirectory.LotStatus status,Instant registeredAt){}
    public record LotStatusRequest(LogisticsDirectory.LotStatus status){}
    public record ReceiptRequest(String id,String productId,String lotId,BigDecimal quantity,String unitOfMeasure,Instant occurredAt,String referenceType,String referenceId,BigDecimal unitCost,String currency){}
    public record AdjustmentRequest(String id,String productId,String lotId,LogisticsDirectory.InventoryMovementType type,BigDecimal quantity,String unitOfMeasure,Instant occurredAt,String referenceId,BigDecimal unitCost,String currency){}
    public record ReservationRequest(String id,String productId,String lotId,BigDecimal quantity,String unitOfMeasure,String referenceType,String referenceId,Instant createdAt,Instant expiresAt){}
    public record FefoReservationRequest(String id,String productId,BigDecimal quantity,String unitOfMeasure,String referenceType,String referenceId,Instant expiresAt){}
    public record TransferRequest(String id,long organizationId,Long unitId,String productId,String lotId,String sourceLocationId,String destinationLocationId,BigDecimal quantity,String unitOfMeasure,Instant occurredAt,String referenceType,String referenceId){}
    public record ShipmentRequest(String id,long organizationId,Long unitId,String reference,String originLocationId,String destinationLocationId,String carrier,String trackingNumber,Instant plannedAt,String recipient,String notes){}
    public record ShipmentItemRequest(String id,String productId,String lotId,String serialNumber,BigDecimal quantity,String unitOfMeasure,Map<String,String> metadata){}
    public record ShipmentEventRequest(String id,LogisticsDirectory.ShipmentEventType type,Instant occurredAt,String locationId,String description,String evidenceReference,Map<String,String> metadata){}
    public record ImportRequest(String id,long organizationId,Long unitId,String reference,String supplierId,String supplierCountry,String purchaseReference,String currency,BigDecimal exchangeRate,String shipmentId,java.time.LocalDate orderedOn,java.time.LocalDate estimatedArrival,String destinationLocationId,String notes){}
    public record ImportDocumentRequest(String id,LogisticsDirectory.ImportDocumentType type,String documentReference,String fileName,String checksum,Instant registeredAt,Map<String,String> metadata){}
    public record ImportExpenseRequest(String id,String category,BigDecimal amount,String currency,BigDecimal exchangeRate,BigDecimal baseCurrencyAmount,java.time.LocalDate incurredOn,String documentReference,String notes,Map<String,String> metadata){}
    public record ImportStatusRequest(LogisticsDirectory.ImportStatus status,java.time.LocalDate arrivedOn,java.time.LocalDate clearedOn,String customsReference,String notes){}
    public record ImportLineRequest(String id,String productId,String lotId,BigDecimal quantity,String unitOfMeasure,BigDecimal unitPrice,String currency,BigDecimal exchangeRate,BigDecimal baseUnitPrice,String baseCurrency,String supplierLineReference){}
    public record ImportLineReceiptRequest(String receiptId,BigDecimal quantity,Instant occurredAt){}
}
